-- Characteristics come in any order. COMMENT is one of them, so it may come
-- first, last or in between.
CREATE FUNCTION f1(a INT) RETURNS INT
DETERMINISTIC
COMMENT 'between'
NO SQL
    RETURN a;

CREATE FUNCTION f2(a INT) RETURNS INT
LANGUAGE SQL
NOT DETERMINISTIC
READS SQL DATA
SQL SECURITY DEFINER
COMMENT 'last'
    RETURN a;

CREATE PROCEDURE p1()
COMMENT 'first'
SQL SECURITY INVOKER
MODIFIES SQL DATA
LANGUAGE SQL
DETERMINISTIC
    SELECT 1;
